const rawMessage = $('Webhook_Incoming').item.json.body.message || "";
const sessionId = $('Webhook_Incoming').item.json.body.sessionId || "unknown";

// Handle Gemini rate limit or API error
const geminiResponse = $input.first().json;
if (!geminiResponse.candidates) {
  return [{ json: {
    name: null, phone: null, course_interest: null,
    intent: "manual_review", urgency_words: false,
    extraction_confidence: "low",
    summary: "API rate limit or error",
    raw_message: rawMessage, session_id: sessionId,
    created_at: new Date().toISOString(),
    last_contacted_at: new Date().toISOString(),
    priority_score: 0
  }}];
}

const geminiText = geminiResponse.candidates[0].content.parts[0].text;
const clean = geminiText.replace(/```json|```/g, "").trim();

let parsed;
try {
  parsed = JSON.parse(clean);
} catch (e) {
  parsed = {
    name: null,
    phone: null,
    course_interest: null,
    intent: "manual_review",
    urgency_words: false,
    extraction_confidence: "low",
    summary: "Failed to parse AI extraction"
  };
}

// Normalize phone to string
parsed.phone = parsed.phone ? String(parsed.phone) : null;

// Attach raw message
parsed.raw_message = rawMessage;
parsed.session_id = sessionId;


// Compute timestamps once
const now = new Date().toISOString();
parsed.created_at = now;
parsed.last_contacted_at = now;

// Priority score
let score = 0;
if (parsed.phone) score += 30;
if (parsed.course_interest && parsed.course_interest !== "other" && parsed.course_interest !== null) score += 25;
if (parsed.extraction_confidence === "high") score += 20;
if (parsed.urgency_words === true) score += 15;
if (parsed.intent === "new_enquiry") score += 10;
parsed.priority_score = score;

return [{ json: parsed }];

const catalogue = {
  python: {
    name: "Python for Professionals",
    duration: "3 months",
    mode: "Online + Offline",
    fee: "Rs.12,000",
    projects: "5 real-world projects",
    next_batch: "May 15, 2026"
  },
  web_development: {
    name: "Full Stack Web Development",
    duration: "4 months",
    mode: "Online",
    fee: "Rs.15,000",
    projects: "3 capstone projects",
    next_batch: "May 20, 2026"
  },
  data_science: {
    name: "Data Science & ML",
    duration: "5 months",
    mode: "Online + Offline",
    fee: "Rs.18,000",
    projects: "4 industry datasets",
    next_batch: "June 1, 2026"
  },
  digital_marketing: {
    name: "Digital Marketing Mastery",
    duration: "2 months",
    mode: "Online",
    fee: "Rs.8,000",
    projects: "Live campaign management",
    next_batch: "May 12, 2026"
  }
};

// Handle both new lead (Set_LeadData) and duplicate (Set_UpsertData) branches
let input;
let is_returning = false;
try {
  input = $('Set_LeadData').item.json;
} catch(e) {
  input = $('Set_UpsertData').item.json;
  is_returning = true;
}
input.is_returning = is_returning;

// For duplicate branch, also pull course_interest from Parse_JSON
if (!input.course_interest) {
  input = { ...input, ...$('Parse_JSON').item.json };
}

const key = input.course_interest;
const course = catalogue[key] || {
  name: "Our Training Programs",
  duration: "Varies by course",
  mode: "Online + Offline",
  fee: "Contact us for pricing",
  projects: "Hands-on projects included",
  next_batch: "Batches running monthly"
};

return [{
  json: {
    ...input,
    course
  }
}];

